#!/usr/bin/env python3
"""Hindi Sounds — one-file Python edition.

Requires Python 3.12+ and PySide6:
    python -m pip install PySide6==6.11.1
    python HindiSounds_Standalone.py

Optional controller support:
    python -m pip install pygame-ce==2.5.8

All 46 recordings, the Devanagari font, icon, and credits are embedded below.
Playback works offline. Assets are unpacked to a temporary folder while running;
settings are saved in the same user settings folder as the desktop edition.
To save the assets and full license texts: --extract-assets DIRECTORY

Audio: Mansi Bajaj / Hindi at the University of Texas at Austin, CC BY 4.0.
https://hindi.la.utexas.edu/resources/pronouncing-the-hindi-alphabet/
https://creativecommons.org/licenses/by/4.0/
Recordings were excerpted and volume-normalized. Font: Noto Sans Devanagari,
SIL OFL 1.1. Full notices are included in the embedded archive.

Generated by tools/build_single_file.py from the modular application source.
"""
from __future__ import annotations

import base64 as _hs_base64
import hashlib as _hs_hashlib
import io as _hs_io
from pathlib import Path as _hs_Path
import sys as _hs_sys
import tempfile as _hs_tempfile
import zipfile as _hs_zipfile

try:
    import PySide6
except ModuleNotFoundError as _hs_error:
    if _hs_error.name != 'PySide6':
        raise
    raise SystemExit('Hindi Sounds needs PySide6. Install it once with:\n'
                     '  python -m pip install PySide6==6.11.1') from None

_hs_asset_directory = None
_hs_font_ids = []

# ===== settings.py =====
import json
import os
import sys
from pathlib import Path

DEFAULTS = {"group": "all", "gap_ms": 1400, "volume": 0.85, "window_mode": "windowed", "letter_id": "01"}
GAPS = (700, 1000, 1400, 2000, 2500, 3500, 5000)

def asset_root() -> Path:
    if _hs_asset_directory is None:
        raise RuntimeError('Embedded assets have not been unpacked')
    return _hs_asset_directory

def state_root() -> Path:
    override = os.environ.get("HINDI_SOUNDS_APPDATA_DIR")
    return Path(override) if override else Path(os.environ.get("LOCALAPPDATA", Path.home())) / "HindiSoundsApp"

def load_settings() -> dict:
    result = dict(DEFAULTS)
    try:
        data = json.loads((state_root() / "settings.json").read_text(encoding="utf-8"))
        if not isinstance(data, dict): return result
        if data.get("group") in ("all", "vowels", "consonants"): result["group"] = data["group"]
        if data.get("gap_ms") in GAPS: result["gap_ms"] = data["gap_ms"]
        if isinstance(data.get("volume"), (int, float)) and 0 <= data["volume"] <= 1: result["volume"] = data["volume"]
        if data.get("window_mode") in ("windowed", "fullscreen", "borderless"): result["window_mode"] = data["window_mode"]
        if isinstance(data.get("letter_id"), str): result["letter_id"] = data["letter_id"]
    except (OSError, ValueError): pass
    return result

def save_settings(data: dict) -> None:
    root = state_root()
    root.mkdir(parents=True, exist_ok=True)
    temporary = root / "settings.tmp"
    temporary.write_text(json.dumps(data, indent=2), encoding="utf-8")
    temporary.replace(root / "settings.json")

# ===== controller.py =====
import os
import time
from dataclasses import dataclass, field

os.environ.setdefault("PYGAME_HIDE_SUPPORT_PROMPT", "1")

from PySide6.QtCore import QObject, QTimer, Signal


@dataclass
class NavigationRepeater:
    initial_delay: float = 0.36
    repeat_delay: float = 0.095
    _pressed_at: dict[str, float] = field(default_factory=dict)
    _repeated_at: dict[str, float] = field(default_factory=dict)

    def update(self, action: str, pressed: bool, now: float) -> bool:
        if not pressed:
            self._pressed_at.pop(action, None)
            self._repeated_at.pop(action, None)
            return False
        if action not in self._pressed_at:
            self._pressed_at[action] = now
            self._repeated_at[action] = now
            return True
        if now - self._pressed_at[action] < self.initial_delay:
            return False
        if now - self._repeated_at[action] >= self.repeat_delay:
            self._repeated_at[action] = now
            return True
        return False


class ControllerManager(QObject):
    action = Signal(str)
    connection_changed = Signal(str)

    BUTTON_ACTIONS = {
        "CONTROLLER_BUTTON_A": "accept",
        "CONTROLLER_BUTTON_B": "back",
        "CONTROLLER_BUTTON_X": "extra",
        "CONTROLLER_BUTTON_Y": "english",
        "CONTROLLER_BUTTON_BACK": "help",
        "CONTROLLER_BUTTON_START": "menu",
        "CONTROLLER_BUTTON_LEFTSHOULDER": "page_left",
        "CONTROLLER_BUTTON_RIGHTSHOULDER": "page_right",
        "CONTROLLER_BUTTON_DPAD_UP": "up",
        "CONTROLLER_BUTTON_DPAD_DOWN": "down",
        "CONTROLLER_BUTTON_DPAD_LEFT": "left",
        "CONTROLLER_BUTTON_DPAD_RIGHT": "right",
    }

    def __init__(self, parent: QObject | None = None, dead_zone: float = 0.58):
        super().__init__(parent)
        self.dead_zone = dead_zone
        self._pygame = None
        self._controller_api = None
        self._controller = None
        self._buttons: dict[str, bool] = {}
        self._repeater = NavigationRepeater()
        self._timer = QTimer(self)
        self._timer.setInterval(16)
        self._timer.timeout.connect(self.poll)
        self._initialize()

    def _initialize(self) -> None:
        try:
            import pygame
            from pygame._sdl2 import controller

            pygame.init()
            controller.init()
            self._pygame = pygame
            self._controller_api = controller
            self._open_first()
            self._timer.start()
        except Exception as exc:
            self.connection_changed.emit(f"Controller input unavailable: {exc}")

    def _open_first(self) -> None:
        if not self._controller_api or self._controller is not None:
            return
        try:
            if self._controller_api.get_count() > 0:
                self._controller = self._controller_api.Controller(0)
                self.connection_changed.emit(f"Controller connected: {self._controller.name}")
        except Exception:
            self._controller = None

    @property
    def connected(self) -> bool:
        try:
            return bool(self._controller and self._controller.attached())
        except Exception:
            return False

    def poll(self) -> None:
        if not self._pygame:
            return
        try:
            self._pygame.event.pump()
            if self._controller and not self._controller.attached():
                self._controller = None
                self._buttons.clear()
                self.connection_changed.emit("Controller disconnected")
            self._open_first()
            if not self._controller:
                return
            now = time.monotonic()
            states: dict[str, bool] = {}
            for constant_name, action in self.BUTTON_ACTIONS.items():
                constant = getattr(self._pygame, constant_name)
                states[action] = bool(self._controller.get_button(constant))
            x = self._controller.get_axis(self._pygame.CONTROLLER_AXIS_LEFTX) / 32768.0
            y = self._controller.get_axis(self._pygame.CONTROLLER_AXIS_LEFTY) / 32768.0
            if abs(x) > abs(y):
                states["left"] = states["left"] or x < -self.dead_zone
                states["right"] = states["right"] or x > self.dead_zone
            else:
                states["up"] = states["up"] or y < -self.dead_zone
                states["down"] = states["down"] or y > self.dead_zone
            repeatable = {"up", "down", "left", "right"}
            for action, pressed in states.items():
                previous = self._buttons.get(action, False)
                fire = self._repeater.update(action, pressed, now) if action in repeatable else pressed and not previous
                if fire:
                    self.action.emit(action)
            self._buttons = states
        except Exception as exc:
            self._controller = None
            self.connection_changed.emit(f"Controller input recovered from error: {exc}")

    def shutdown(self) -> None:
        self._timer.stop()
        try:
            if self._controller:
                self._controller.quit()
            if self._controller_api:
                self._controller_api.quit()
            if self._pygame:
                self._pygame.quit()
        except Exception:
            pass

# ===== player.py =====
"""Event-driven, cancellable playback for the Hindi letter practice window."""

import math
from pathlib import Path

from PySide6.QtCore import QObject, QTimer, QUrl, Signal
from PySide6.QtMultimedia import QAudioOutput, QMediaPlayer


class SoundPlayer(QObject):
    """Play individual local recordings, optionally repeating the chosen group.

    ``changed`` observers can always read a valid ``current`` item. Every sound
    owns its media object and timers so signals queued by an interrupted sound
    cannot change the current selection or resume a canceled loop.
    """

    changed = Signal()
    error = Signal(str)
    LOAD_TIMEOUT_MS = 10_000

    def __init__(self, items: list[dict], audio_root: Path, parent=None):
        super().__init__(parent)
        if not items:
            raise ValueError("The letter collection is empty.")
        if any(not all(item.get(key) for key in ("id", "letter", "audio")) for item in items):
            raise ValueError("Every letter needs an id, letter, and audio filename.")
        self._all_items = list(items)
        self.items = list(items)
        self.audio_root = Path(audio_root).resolve()
        self.index = 0
        self.round = 1
        self.looping = False
        self.sounding = False
        self.phase = "ready"
        self.gap_ms = 1400
        self.volume = 0.85
        self.group = "all"
        self._generation = 0
        self._finished = False
        self._closed = False
        self._media = None
        self._output = None
        self._gap_timer = None
        self._load_timer = None

    @property
    def current(self) -> dict:
        return self.items[self.index]

    @property
    def total(self) -> int:
        return len(self.items)

    @property
    def busy(self) -> bool:
        return self.phase in ("loading", "sounding")

    def start(self):
        if self._closed:
            return
        self.looping = True
        self._play_current()

    def pause(self):
        if self._closed:
            return
        self.looping = False
        self._cancel_current()
        self.phase = "paused"
        self.changed.emit()

    def toggle(self):
        if self.looping or self.busy:
            self.pause()
        else:
            self.start()

    def replay(self):
        if not self._closed:
            self._play_current()

    def move(self, delta):
        if self._closed:
            return
        self._cancel_current()
        self._advance(int(delta))
        self._play_current()

    def select(self, index):
        if self._closed or not isinstance(index, int) or not 0 <= index < self.total:
            return
        self._cancel_current()
        self.index = index
        self._play_current()

    def set_group(self, kind):
        if self._closed:
            return
        if kind == "all":
            selected = list(self._all_items)
        elif kind == "vowels":
            selected = [item for item in self._all_items if item.get("category") in ("vowel", "sign")]
        elif kind == "consonants":
            selected = [item for item in self._all_items if item.get("category") == "consonant"]
        else:
            raise ValueError(f"Unknown letter group: {kind}")
        if not selected:
            self._cancel_current()
            self._fail(self._generation, "This group has no letters to play.")
            return
        self._cancel_current()
        self.items = selected
        self.index = 0
        self.round = 1
        self.group = kind
        if self.looping:
            self._play_current()
        else:
            self.phase = "ready"
            self.changed.emit()

    def set_volume(self, value):
        value = float(value)
        if not math.isfinite(value):
            raise ValueError("Volume must be a finite number.")
        self.volume = min(1.0, max(0.0, value))
        if self._output is not None:
            self._output.setVolume(self.volume)

    def shutdown(self):
        if self._closed:
            return
        self.looping = False
        self._cancel_current()
        self.phase = "paused"
        self._closed = True
        self.changed.emit()

    def _advance(self, delta):
        wraps, self.index = divmod(self.index + delta, self.total)
        self.round = max(1, self.round + wraps)

    def _cancel_current(self):
        # Invalidate first: stopping Qt media can emit signals synchronously.
        self._generation += 1
        self._finished = False
        for name in ("_gap_timer", "_load_timer"):
            timer = getattr(self, name)
            setattr(self, name, None)
            if timer is not None:
                timer.stop()
                timer.deleteLater()
        media, output = self._media, self._output
        self._media = self._output = None
        if media is not None:
            media.stop()
            media.deleteLater()
        if output is not None:
            output.deleteLater()
        self.sounding = False

    def _live(self, generation):
        return not self._closed and generation == self._generation and not self._finished

    def _play_current(self):
        self._cancel_current()
        generation = self._generation
        self.phase = "loading"
        self.changed.emit()
        # A changed observer may pause or navigate. Do not start the old sound.
        if not self._live(generation):
            return
        path = (self.audio_root / self.current["audio"]).resolve()
        if not path.is_file():
            self._fail(generation, f"The recording for {self.current['letter']} is missing: {path.name}.")
            return
        try:
            output = QAudioOutput(self)
            output.setVolume(self.volume)
            media = QMediaPlayer(self)
            self._output, self._media = output, media
            media.setAudioOutput(output)
            media.playbackStateChanged.connect(lambda state: self._state_changed(generation, state))
            media.mediaStatusChanged.connect(lambda status: self._status_changed(generation, status))
            media.errorOccurred.connect(lambda code, message: self._media_error(generation, code, message))
            self._arm_load_timeout(generation)
            media.setSource(QUrl.fromLocalFile(str(path)))
            if self._live(generation):
                media.play()
        except Exception as exc:
            self._fail(generation, f"The audio player could not start: {exc}")

    def _cancel_load_timeout(self):
        timer, self._load_timer = self._load_timer, None
        if timer is not None:
            timer.stop()
            timer.deleteLater()

    def _arm_load_timeout(self, generation):
        if self._load_timer is not None:
            return
        timer = QTimer(self)
        timer.setSingleShot(True)
        timer.timeout.connect(lambda: self._load_timed_out(generation, timer))
        self._load_timer = timer
        timer.start(self.LOAD_TIMEOUT_MS)

    def _load_timed_out(self, generation, timer):
        if self._load_timer is timer and self.phase == "loading" and self._live(generation):
            self._fail(generation, "The recording took too long to load. Press Play to try again.")

    def _state_changed(self, generation, state):
        if not self._live(generation):
            return
        if state == QMediaPlayer.PlaybackState.PlayingState:
            self._cancel_load_timeout()
            self.sounding = True
            self.phase = "sounding"
            self.changed.emit()
        elif self._media.mediaStatus() == QMediaPlayer.MediaStatus.EndOfMedia:
            self._finish(generation)
        elif self.sounding:
            self.sounding = False
            self.phase = "loading"
            self._arm_load_timeout(generation)
            self.changed.emit()

    def _status_changed(self, generation, status):
        if not self._live(generation):
            return
        if status == QMediaPlayer.MediaStatus.EndOfMedia:
            self._finish(generation)
        elif status == QMediaPlayer.MediaStatus.InvalidMedia:
            self._media_error(generation, QMediaPlayer.Error.FormatError, self._media.errorString())
        elif status == QMediaPlayer.MediaStatus.StalledMedia:
            self.sounding = False
            self.phase = "loading"
            self._arm_load_timeout(generation)
            self.changed.emit()
        elif status in (QMediaPlayer.MediaStatus.LoadedMedia, QMediaPlayer.MediaStatus.BufferedMedia):
            if self._media.playbackState() == QMediaPlayer.PlaybackState.PlayingState:
                self._state_changed(generation, QMediaPlayer.PlaybackState.PlayingState)

    def _finish(self, generation):
        if not self._live(generation):
            return
        self._finished = True
        self._cancel_load_timeout()
        self.sounding = False
        self.phase = "gap" if self.looping else "ready"
        self.changed.emit()
        if generation != self._generation or not self.looping or self._closed:
            return
        timer = QTimer(self)
        timer.setSingleShot(True)
        timer.timeout.connect(lambda: self._next_after_gap(generation))
        self._gap_timer = timer
        timer.start(max(0, int(self.gap_ms)))

    def _next_after_gap(self, generation):
        if generation != self._generation or not self.looping or self._closed:
            return
        self._advance(1)
        self._play_current()

    def _media_error(self, generation, code, message):
        if code == QMediaPlayer.Error.NoError or not self._live(generation):
            return
        detail = str(message).strip() or "The recording could not be decoded or played."
        self._fail(generation, f"Could not play {self.current['letter']}: {detail}")

    def _fail(self, generation, message):
        if generation != self._generation or self._closed or self._finished:
            return
        self.looping = False
        self._cancel_current()
        self.phase = "error"
        self.changed.emit()
        self.error.emit(str(message))

