def _hs_unpack_assets(destination):
    """Unpack the trusted embedded assets, checking integrity and safe paths."""
    payload = _hs_base64.b85decode(b''.join(_hs_payload.split()))
    if _hs_hashlib.sha256(payload).hexdigest() != _hs_payload_sha256:
        raise RuntimeError('The embedded recordings are damaged; download the script again.')
    destination = _hs_Path(destination).resolve()
    with _hs_zipfile.ZipFile(_hs_io.BytesIO(payload)) as archive:
        for member in archive.infolist():
            target = (destination / member.filename).resolve()
            if not target.is_relative_to(destination):
                raise RuntimeError('Invalid embedded asset path')
        archive.extractall(destination)
    return destination


def _hs_release_assets():
    # Windows may keep fonts/media open until Qt processes deferred deletions.
    import gc
    from PySide6.QtCore import QCoreApplication
    app = QApplication.instance()
    if app is not None:
        QCoreApplication.sendPostedEvents(None, QEvent.Type.DeferredDelete)
        for font_id in _hs_font_ids:
            if font_id >= 0:
                QFontDatabase.removeApplicationFont(font_id)
        app.processEvents()
    _hs_font_ids.clear()
    gc.collect()


def _hs_start():
    global _hs_asset_directory
    if '--extract-assets' in _hs_sys.argv[1:]:
        parser = argparse.ArgumentParser(description='Extract Hindi Sounds assets and license texts')
        parser.add_argument('--extract-assets', required=True, type=_hs_Path)
        options = parser.parse_args()
        target = _hs_unpack_assets(options.extract_assets)
        print(f'Assets and notices saved to {target}')
        return 0
    with _hs_tempfile.TemporaryDirectory(prefix='hindi-sounds-assets-',
                                          ignore_cleanup_errors=True) as folder:
        _hs_asset_directory = _hs_unpack_assets(folder) / 'assets'
        try:
            return run()
        finally:
            _hs_release_assets()
            _hs_asset_directory = None


if __name__ == '__main__':
    raise SystemExit(_hs_start())
